{
  "checks": [
    {
      "scenario": "REQ-2.1#1",
      "requirement": "REQ-2.1",
      "title": "Note Listing",
      "category": "read-list",
      "rationale": "Opening the entry URL renders the seeded home page. The pinned seed note 'Sprint goals' and the regular seed note 'Groceries' are the observable note cards from the state contract, so asserting both visible texts checks the notes list and the pinned/regular seed set.",
      "given": [
        { "op": "open" }
      ],
      "when": [],
      "then": [
        { "op": "expectText", "target": { "name": ["Sprint goals"], "via": "text" } },
        { "op": "expectText", "target": { "name": ["Groceries"], "via": "text" } },
        {
          "op": "unknown",
          "reason": "ambiguous-assertion",
          "detail": "The exact section heading or visual separator text for pinned vs regular notes is not declared in the contract exact-text list, so the two seeded cards are asserted individually."
        }
      ]
    },
    {
      "scenario": "REQ-2.2#1",
      "requirement": "REQ-2.2",
      "title": "Create Note",
      "category": "create",
      "rationale": "The 'Take a note' composer is the declared navigation control for entering the note editor. Unique scenario-derived title and content are filled in the expanded editor, the editor is closed with Escape to commit autosave, and the new note card is asserted by its generated title and content.",
      "given": [
        { "op": "open" },
        {
          "op": "bind",
          "variable": "noteTitle",
          "value": "QA Created Note 2.2",
          "source": "Scenario-derived unique title for the note created in REQ-2.2; it does not collide with any seeded note title."
        },
        {
          "op": "bind",
          "variable": "noteContent",
          "value": "QA content 2.2",
          "source": "Scenario-derived unique content for the same created note, allowing an unambiguous visible-text assertion."
        }
      ],
      "when": [
        { "op": "click", "target": { "name": ["Take a note"], "via": "ladder" } },
        {
          "op": "fill",
          "target": { "name": ["Title", "Note title"], "via": "field" },
          "value": { "variable": "noteTitle" }
        },
        {
          "op": "fill",
          "target": {
            "name": ["Take a note...", "Take a note", "Note text", "Content"],
            "via": "field"
          },
          "value": { "variable": "noteContent" }
        },
        { "op": "press", "key": "Escape" }
      ],
      "then": [
        { "op": "expectAbsent", "target": { "name": ["Title", "Note title"], "via": "field" } },
        { "op": "expectText", "target": { "name": ["${noteTitle}"], "via": "text" } },
        { "op": "expectText", "target": { "name": ["${noteContent}"], "via": "text" } }
      ]
    },
    {
      "scenario": "REQ-2.4#1",
      "requirement": "REQ-2.4",
      "title": "Update Note",
      "category": "edit",
      "rationale": "The seeded note 'Project ideas' has initial content 'Initial editable content'. Opening its card, replacing the content with a unique scenario-derived string, and closing the editor verifies persistence when the updated content is rendered and the old initial content is absent.",
      "given": [
        { "op": "open" },
        {
          "op": "bind",
          "variable": "updatedContent",
          "value": "QA updated content 2.4",
          "source": "Scenario-derived unique replacement content for the seeded 'Project ideas' note; it does not match any existing note text."
        }
      ],
      "when": [
        { "op": "click", "target": { "name": ["Project ideas"], "via": "text" } },
        {
          "op": "fill",
          "target": {
            "name": ["Take a note...", "Take a note", "Note text", "Content"],
            "via": "field",
            "within": { "name": ["Project ideas"], "via": "text" }
          },
          "value": { "variable": "updatedContent" }
        },
        { "op": "press", "key": "Escape" }
      ],
      "then": [
        { "op": "expectAbsent", "target": { "name": ["Title", "Note title"], "via": "field" } },
        { "op": "expectText", "target": { "name": ["${updatedContent}"], "via": "text" } },
        { "op": "expectAbsent", "target": { "name": ["Initial editable content"], "via": "text" } }
      ]
    }
  ]
}
